Addition.Text:
# Generated from current AGOT crown effects.
# Automatic grants/finds have no known maker; preserve OWNER and all artifact properties.

apf_create_artifact_aegon_i_crown_without_creator_effect = {
	# Get the character the artifact is being made for.
	$OWNER$ = { save_scope_as = owner }


	set_artifact_rarity_illustrious = yes

	# Create the artifact
	create_artifact = {
		name = aegon_i_crown_name
		description = aegon_i_crown_description
		type = helmet
		visuals = aegon_i_crown_visuals
		wealth = scope:wealth
		quality = scope:quality
		template = aegon_i_crown_template
		modifier = aegon_i_crown_modifier
		save_scope_as = newly_created_artifact

		decaying = no
	}

	scope:newly_created_artifact ?= {
		set_variable = { name = crown_aegon_i_artifact value = yes }
		set_variable = { name = historical_unique_artifact value = yes }
	}
}

